<?php
require __DIR__.'/bootstrap.php';auth();require __DIR__.'/layout.php';$pdo=db();$msg='';$err='';
if(isset($_GET['export'])){header('Content-Type:text/csv; charset=utf-8');header('Content-Disposition:attachment; filename="congrate_export.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['DATE','이름(대상)','경조일자','경조대상','경조금','기타사항','휴대전화']);foreach($pdo->query('SELECT e.original_date,p.name,e.event_date,e.event_type,e.amount,e.memo,p.phone FROM cg_expenses e JOIN cg_people p ON p.id=e.person_id ORDER BY e.id') as $r)fputcsv($out,[$r['original_date'],$r['name'],$r['event_date'],$r['event_type'],$r['amount'],$r['memo'],$r['phone']]);exit;}
if($_SERVER['REQUEST_METHOD']==='POST')try{check_csrf();if(!isset($_FILES['csv'])||$_FILES['csv']['error']!==UPLOAD_ERR_OK||$_FILES['csv']['size']>5*1024*1024)throw new RuntimeException('5MB 이하 CSV 파일을 선택하세요.');$fp=fopen($_FILES['csv']['tmp_name'],'r');$headers=fgetcsv($fp);if(!$headers)throw new RuntimeException('빈 파일');$headers[0]=preg_replace('/^\xEF\xBB\xBF/','',$headers[0]);$required=['DATE','이름(대상)','경조일자','경조대상','경조금','기타사항'];foreach($required as $key)if(!in_array($key,$headers,true))throw new RuntimeException('필수 열 없음: '.$key);$count=0;$skip=0;$pdo->beginTransaction();while(($values=fgetcsv($fp))!==false){$r=array_combine($headers,array_pad(array_slice($values,0,count($headers)),count($headers),''));$name=trim($r['이름(대상)']);$date=trim($r['경조일자']);$type=trim($r['경조대상']);$amount=money($r['경조금']);if(!$name||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||!$type||!$amount){$skip++;continue;}$key=hash('sha256',implode('|',[$r['DATE'],$name,$date,$type,$r['경조금'],$r['기타사항']]));$st=$pdo->prepare('SELECT id FROM cg_expenses WHERE import_key=?');$st->execute([$key]);if($st->fetch()){$skip++;continue;}$st=$pdo->prepare('SELECT id FROM cg_people WHERE name=? ORDER BY id LIMIT 1');$st->execute([$name]);$pid=$st->fetchColumn();if(!$pid){$pdo->prepare('INSERT INTO cg_people(name,phone) VALUES(?,?)')->execute([$name,phone($r['휴대전화']??'')?:null]);$pid=$pdo->lastInsertId();}$pdo->prepare('INSERT INTO cg_expenses(person_id,event_date,event_type,amount,memo,original_date,import_key) VALUES(?,?,?,?,?,?,?)')->execute([$pid,$date,$type,$amount,$r['기타사항'],$r['DATE'],$key]);$count++;}fclose($fp);$pdo->commit();$msg="가져오기 완료: {$count}건, 중복/제외 {$skip}건";}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$err=$e->getMessage();}
top('CSV 가져오기 / 내보내기');if($msg)echo '<div class="alert alert-success">'.h($msg).'</div>';if($err)echo '<div class="alert alert-danger">'.h($err).'</div>';?><div class="card p-4"><p>첨부된 초기 CSV 파일을 한 번 업로드하세요. 동일 원본 행은 재업로드 시 중복 방지됩니다.</p><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="file" class="form-control mb-3" name="csv" accept=".csv" required><button class="btn btn-primary">CSV 가져오기</button> <a class="btn btn-outline-success" href="?export=1">전체 CSV 내보내기</a></form></div><?php bottom();?>
